# Genera le inquadrature dei primi 30 secondi di «Nervi saldi» (Runway). Salta quelle già fatte.
import sys, os; sys.path.insert(0, "../concept"); os.chdir(os.path.dirname(os.path.abspath(__file__)))
from rw import talk, shot
C = "../concept/"; S = "3D animated feature film, same characters and same gym as the reference image, realistic body mechanics and weight. "
tot = 0
def need(n): return not os.path.exists(n + ".mp4")
if need("out/i1"): tot += shot("out/i1", C+"g1.png", S+"Low-angle shot. The blond striker presses the heavy barbell to full lockout with effort, then racks it onto the supports with a loud clank, the plates rattle, chalk dust falls; he sits up quickly on the bench and throws both arms up in triumph. Camera rises with him.", dur=5, model="kling3.0_pro")
if need("out/i3"): tot += talk("out/i3", C+"g3.png", "out/b2.mp3", S+"Medium close-up of the coach in the orange tracksuit and black cap. Without looking up from his notebook at first, he speaks the line in the audio with accurate lip sync, deadpan and dry; halfway through he pulls a yellow tailor's measuring tape out of his jacket pocket and finally lifts his eyes. Minimal, controlled movement. Static camera.", dur=4)
if need("out/i4"): tot += shot("out/i4", C+"g4.png", S+"Close-up detail. The coach's hands pull the yellow measuring tape snug around the flexed upper arm and hold it; the striker flexes harder, the muscle tenses; the coach's thumb taps the number on the tape. Slight handheld push-in.", dur=3, model="kling3.0_standard", ratio="720:1280")
if need("out/i5"): tot += talk("out/i5", C+"g5.png", "out/b3.mp3", S+"Close-up of the coach in the orange tracksuit and black cap holding a yellow measuring tape. He speaks the line in the audio with accurate lip sync, completely deadpan; after the pause he raises one eyebrow and lets the tape snap back into its case. Almost no head movement. Slow push-in.", dur=5)
if need("out/i6"): tot += talk("out/i6", C+"g6.png", "out/b4.mp3", S+"Medium shot of the young footballer in the green number 10 jersey sitting on a wooden box with a water bottle. He leans forward and speaks the line in the audio with accurate lip sync, curious and puzzled: he tilts his head, lifts a hand in a questioning gesture, eyebrows up. Gentle camera drift to the side.", dur=4)
if need("out/i7"): tot += talk("out/i7", C+"g7.png", "out/b5.mp3", S+"Medium close-up of the blond striker in the red sleeveless top holding a yellow measuring tape. He speaks the line in the audio with accurate lip sync, confident and dismissive: he waves the tape, shakes his head, then taps his own biceps and shrugs. Lively, energetic acting. Slight low angle.", dur=4)
if need("out/i8"): tot += shot("out/i8", C+"g8.png", S+"Close-up. The coach looks straight into the camera, arms crossed, slowly raises one eyebrow even higher and gives the smallest shake of the head, then a tiny smirk. Slow push-in.", dur=3, model="kling3.0_standard", ratio="720:1280")
print("crediti stimati", tot)
